import React, { useEffect, useState } from 'react';
import api from '../services/api';
import { Timesheet, Employee, Project, TimesheetRow, OTCalculation } from '../types';
import { format, addDays, startOfWeek } from 'date-fns';
import { User } from '../types';

interface TimesheetPageProps {
  user: User | null;
}

export function TimesheetPage({ user }: TimesheetPageProps) {
  const [timesheets, setTimesheets] = useState<Timesheet[]>([]);
  const [selectedTimesheet, setSelectedTimesheet] = useState<Timesheet | null>(null);
  const [rows, setRows] = useState<TimesheetRow[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [otCalculations, setOTCalculations] = useState<OTCalculation[]>([]);
  const [weekDate, setWeekDate] = useState<Date>(startOfWeek(new Date(), { weekStartsOn: 1 }));
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function fetchData() {
    try {
      setError(null);
      const [sheetsData, empsData, projsData] = await Promise.all([
        api.getTimesheets(),
        api.getEmployees(),
        api.getProjects(),
      ]);

      setTimesheets(sheetsData);
      setEmployees(empsData);
      setProjects(projsData);

      const weekStart = format(weekDate, 'yyyy-MM-dd');
      const currentSheet = sheetsData.find((t: Timesheet) => t.week_start_date === weekStart);
      if (currentSheet) {
        await loadTimesheet(currentSheet.id);
      }
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to load timesheets');
    } finally {
      setLoading(false);
    }
  }

  async function loadTimesheet(id: number) {
    try {
      const detail = await api.getTimesheetDetail(id);
      setSelectedTimesheet(detail.timesheet);
      setRows(detail.rows);
      setOTCalculations(detail.ot_calculations);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to load timesheet');
    }
  }

  async function createTimesheetForWeek() {
    const weekStart = format(weekDate, 'yyyy-MM-dd');
    const existing = timesheets.find((t) => t.week_start_date === weekStart);
    if (existing) {
      await loadTimesheet(existing.id);
      return;
    }
    try {
      setSaving(true);
      setError(null);
      const result = await api.createTimesheet(weekStart, []);
      const updatedSheets = await api.getTimesheets();
      setTimesheets(updatedSheets);
      await loadTimesheet(result.id);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to create timesheet');
    } finally {
      setSaving(false);
    }
  }

  async function saveTimesheet() {
    if (!selectedTimesheet) return;
    try {
      setSaving(true);
      setError(null);
      const rowsToSave = rows.map((row) => ({
        id: row.id,
        employee_id: row.employee_id,
        project_id: row.project_id,
        monday: row.monday,
        tuesday: row.tuesday,
        wednesday: row.wednesday,
        thursday: row.thursday,
        friday: row.friday,
        saturday: row.saturday,
        sunday: row.sunday,
      }));
      await api.updateTimesheetRows(selectedTimesheet.id, rowsToSave);
      // Reload to get updated OT calculations
      await loadTimesheet(selectedTimesheet.id);
      alert('Timesheet saved successfully');
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to save timesheet');
    } finally {
      setSaving(false);
    }
  }

  async function submitTimesheet() {
    if (!selectedTimesheet) return;
    try {
      setSaving(true);
      setError(null);
      await api.submitTimesheet(selectedTimesheet.id);
      alert('Timesheet submitted for approval');
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to submit timesheet');
    } finally {
      setSaving(false);
    }
  }

  async function approveTimesheet(id: number) {
    try {
      setError(null);
      await api.approveTimesheet(id);
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to approve timesheet');
    }
  }

  async function rejectTimesheet(id: number) {
    const reason = prompt('Rejection reason (optional):') || '';
    try {
      setError(null);
      await api.rejectTimesheet(id, reason);
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to reject timesheet');
    }
  }

  function updateRow(index: number, field: string, value: number) {
    const newRows = [...rows];
    (newRows[index] as any)[field] = value;
    const days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
    let total = 0;
    for (const day of days) {
      total += parseFloat((newRows[index] as any)[day]) || 0;
    }
    newRows[index].total_hours = Math.round(total * 100) / 100;
    setRows(newRows);
  }

  function updateRowEmployee(index: number, employeeId: number) {
    const newRows = [...rows];
    const emp = employees.find((e) => e.id === employeeId);
    newRows[index] = {
      ...newRows[index],
      employee_id: employeeId,
      employee_name: emp?.name || '',
    };
    setRows(newRows);
  }

  function updateRowProject(index: number, projectId: number) {
    const newRows = [...rows];
    const proj = projects.find((p) => p.id === projectId);
    newRows[index] = {
      ...newRows[index],
      project_id: projectId,
      project_name: proj?.name || '',
    };
    setRows(newRows);
  }

  async function deleteRow(index: number) {
    try {
      if (rows[index].id) {
        await api.deleteTimesheetRow(rows[index].id);
      }
      setRows(rows.filter((_, i) => i !== index));
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to delete row');
    }
  }

  function addNewRow() {
    if (!selectedTimesheet) return;
    const newRow: TimesheetRow = {
      id: 0,
      timesheet_id: selectedTimesheet.id,
      employee_id: employees[0]?.id || 0,
      project_id: projects[0]?.id || 0,
      employee_name: employees[0]?.name || '',
      project_name: projects[0]?.name || '',
      monday: 0,
      tuesday: 0,
      wednesday: 0,
      thursday: 0,
      friday: 0,
      saturday: 0,
      sunday: 0,
      total_hours: 0,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };
    setRows([...rows, newRow]);
  }

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <p className="text-gray-600">Loading timesheets...</p>
      </div>
    );
  }

  const weekStart = format(weekDate, 'yyyy-MM-dd');
  const weekEnd = format(addDays(weekDate, 6), 'MMM dd');
  const weekStartFormatted = format(weekDate, 'MMM dd, yyyy');
  const hasTimesheetForWeek = timesheets.some((t) => t.week_start_date === weekStart);
  const isAdmin = user?.role === 'admin';
  const isSupervisor = user?.role === 'supervisor';
  const canCreateTimesheet = isSupervisor || isAdmin;
  const canEdit = selectedTimesheet && (selectedTimesheet.status === 'draft');

  // Admin view: pending timesheets for approval
  const pendingTimesheets = isAdmin ? timesheets.filter((t) => t.status === 'pending') : [];

  return (
    <div>
      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error}
        </div>
      )}

      {/* Admin: Pending Approvals */}
      {isAdmin && pendingTimesheets.length > 0 && (
        <div className="mb-6 bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-bold text-gray-900 mb-4">
            Pending Approvals ({pendingTimesheets.length})
          </h3>
          <div className="space-y-3">
            {pendingTimesheets.map((t) => (
              <div
                key={t.id}
                className="flex items-center justify-between p-4 bg-yellow-50 border border-yellow-200 rounded-lg"
              >
                <div>
                  <p className="font-medium text-gray-900">
                    Week of {format(new Date(t.week_start_date + 'T12:00:00'), 'MMM dd, yyyy')}
                  </p>
                  <p className="text-sm text-gray-600">Supervisor ID: {t.supervisor_id}</p>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={() => approveTimesheet(t.id)}
                    className="px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-medium hover:bg-green-700"
                  >
                    Approve
                  </button>
                  <button
                    onClick={() => rejectTimesheet(t.id)}
                    className="px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-medium hover:bg-red-700"
                  >
                    Reject
                  </button>
                  <button
                    onClick={() => loadTimesheet(t.id)}
                    className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-200"
                  >
                    View
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Week Navigation */}
      <div className="mb-6 bg-white p-6 rounded-lg shadow">
        <div className="flex flex-wrap items-center gap-4 mb-4">
          <div className="flex items-center gap-2">
            <button
              onClick={() => {
                const newDate = addDays(weekDate, -7);
                setWeekDate(newDate);
                setSelectedTimesheet(null);
                setRows([]);
                setOTCalculations([]);
                const newWeekStart = format(newDate, 'yyyy-MM-dd');
                const sheet = timesheets.find((t) => t.week_start_date === newWeekStart);
                if (sheet) loadTimesheet(sheet.id);
              }}
              className="px-3 py-2 bg-gray-100 hover:bg-gray-200 rounded text-sm font-medium"
            >
              ← Prev
            </button>
            <span className="px-4 py-2 bg-blue-50 text-blue-700 rounded font-medium text-sm">
              {weekStartFormatted} – {weekEnd}
            </span>
            <button
              onClick={() => {
                const newDate = addDays(weekDate, 7);
                setWeekDate(newDate);
                setSelectedTimesheet(null);
                setRows([]);
                setOTCalculations([]);
                const newWeekStart = format(newDate, 'yyyy-MM-dd');
                const sheet = timesheets.find((t) => t.week_start_date === newWeekStart);
                if (sheet) loadTimesheet(sheet.id);
              }}
              className="px-3 py-2 bg-gray-100 hover:bg-gray-200 rounded text-sm font-medium"
            >
              Next →
            </button>
          </div>

          {canCreateTimesheet && !hasTimesheetForWeek && (
            <button
              onClick={createTimesheetForWeek}
              disabled={saving}
              className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium text-sm disabled:opacity-50"
            >
              + New Timesheet for This Week
            </button>
          )}

          {selectedTimesheet && (
            <span
              className={`px-3 py-1 rounded-full text-xs font-semibold uppercase ${
                selectedTimesheet.status === 'approved'
                  ? 'bg-green-100 text-green-700'
                  : selectedTimesheet.status === 'pending'
                  ? 'bg-yellow-100 text-yellow-700'
                  : selectedTimesheet.status === 'rejected'
                  ? 'bg-red-100 text-red-700'
                  : 'bg-gray-100 text-gray-700'
              }`}
            >
              {selectedTimesheet.status}
            </span>
          )}
        </div>

        {selectedTimesheet?.rejection_reason && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded text-red-700 text-sm">
            <strong>Rejected:</strong> {selectedTimesheet.rejection_reason}
          </div>
        )}

        {selectedTimesheet && (
          <div className="flex flex-wrap gap-2">
            {canEdit && (
              <>
                <button
                  onClick={saveTimesheet}
                  disabled={saving}
                  className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium text-sm disabled:opacity-50"
                >
                  {saving ? 'Saving...' : 'Save Draft'}
                </button>
                <button
                  onClick={submitTimesheet}
                  disabled={saving || rows.length === 0}
                  className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-medium text-sm disabled:opacity-50"
                >
                  {saving ? 'Submitting...' : 'Submit for Approval'}
                </button>
              </>
            )}
            {isAdmin && selectedTimesheet.status === 'pending' && (
              <>
                <button
                  onClick={() => approveTimesheet(selectedTimesheet.id)}
                  className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-medium text-sm"
                >
                  Approve
                </button>
                <button
                  onClick={() => rejectTimesheet(selectedTimesheet.id)}
                  className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg font-medium text-sm"
                >
                  Reject
                </button>
              </>
            )}
          </div>
        )}
      </div>

      {/* Timesheet Table */}
      {selectedTimesheet ? (
        <div className="bg-white rounded-lg shadow overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-gray-50 border-b">
              <tr>
                <th className="px-4 py-3 text-left font-semibold text-gray-700 min-w-36">Employee</th>
                <th className="px-4 py-3 text-left font-semibold text-gray-700 min-w-36">Project</th>
                {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((d) => (
                  <th key={d} className="px-2 py-3 text-center font-semibold text-gray-700 w-14">
                    {d}
                  </th>
                ))}
                <th className="px-4 py-3 text-right font-semibold text-gray-700">Total</th>
                {canEdit && (
                  <th className="px-4 py-3 text-center font-semibold text-gray-700">Del</th>
                )}
              </tr>
            </thead>
            <tbody>
              {rows.map((row, idx) => (
                <tr key={idx} className="border-b hover:bg-gray-50">
                  <td className="px-4 py-2">
                    {canEdit ? (
                      <select
                        value={row.employee_id}
                        onChange={(e) => updateRowEmployee(idx, parseInt(e.target.value))}
                        className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
                      >
                        {employees.map((e) => (
                          <option key={e.id} value={e.id}>
                            {e.name}
                          </option>
                        ))}
                      </select>
                    ) : (
                      <span className="font-medium">{row.employee_name}</span>
                    )}
                  </td>
                  <td className="px-4 py-2">
                    {canEdit ? (
                      <select
                        value={row.project_id}
                        onChange={(e) => updateRowProject(idx, parseInt(e.target.value))}
                        className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
                      >
                        {projects.map((p) => (
                          <option key={p.id} value={p.id}>
                            {p.name}
                          </option>
                        ))}
                      </select>
                    ) : (
                      <span className="text-gray-600">{row.project_name}</span>
                    )}
                  </td>
                  {(
                    ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'] as const
                  ).map((day) => (
                    <td key={day} className="px-2 py-2 text-center">
                      {canEdit ? (
                        <input
                          type="number"
                          min="0"
                          max="24"
                          step="0.5"
                          value={(row as any)[day] || 0}
                          onChange={(e) => updateRow(idx, day, parseFloat(e.target.value) || 0)}
                          className="w-12 px-1 py-1 border border-gray-300 rounded text-center text-sm"
                        />
                      ) : (
                        <span>{(row as any)[day] || 0}</span>
                      )}
                    </td>
                  ))}
                  <td className="px-4 py-2 text-right font-semibold">
                    {row.total_hours.toFixed(1)}
                  </td>
                  {canEdit && (
                    <td className="px-4 py-2 text-center">
                      <button
                        onClick={() => deleteRow(idx)}
                        className="text-red-500 hover:text-red-700 text-lg font-bold"
                        title="Delete row"
                      >
                        ×
                      </button>
                    </td>
                  )}
                </tr>
              ))}
              {rows.length === 0 && (
                <tr>
                  <td colSpan={10} className="px-4 py-8 text-center text-gray-500">
                    No rows yet. {canEdit && 'Click "+ Add Row" to start entering hours.'}
                  </td>
                </tr>
              )}
            </tbody>
          </table>

          {canEdit && (
            <div className="px-4 py-4 border-t">
              <button
                onClick={addNewRow}
                disabled={employees.length === 0 || projects.length === 0}
                className="px-4 py-2 bg-blue-50 text-blue-600 hover:bg-blue-100 rounded-lg font-medium text-sm disabled:opacity-50"
              >
                + Add Row
              </button>
              {(employees.length === 0 || projects.length === 0) && (
                <span className="ml-3 text-sm text-red-500">
                  Need at least one employee and one project in Settings first.
                </span>
              )}
            </div>
          )}
        </div>
      ) : (
        <div className="bg-white rounded-lg shadow p-12 text-center">
          <p className="text-gray-500 text-lg mb-4">No timesheet for this week.</p>
          {canCreateTimesheet && (
            <button
              onClick={createTimesheetForWeek}
              disabled={saving}
              className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium disabled:opacity-50"
            >
              {saving ? 'Creating...' : '+ Create Timesheet for This Week'}
            </button>
          )}
        </div>
      )}

      {/* OT Summary */}
      {otCalculations.length > 0 && (
        <div className="mt-6 bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-bold mb-4">OT Calculation Summary</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {otCalculations.map((ot) => {
              const emp = employees.find((e) => e.id === ot.employee_id);
              return (
                <div key={ot.id} className="p-4 bg-gray-50 rounded-lg border">
                  <p className="font-semibold text-gray-900">{emp?.name || `Employee #${ot.employee_id}`}</p>
                  <div className="mt-2 text-sm space-y-1">
                    <p className="text-gray-600">Total: <strong>{Number(ot.total_hours).toFixed(1)} hrs</strong></p>
                    <p className="text-green-600">Regular: {Number(ot.regular_hours).toFixed(1)} hrs</p>
                    {Number(ot.ot_hours) > 0 && (
                      <p className="text-orange-600 font-medium">OT: {Number(ot.ot_hours).toFixed(1)} hrs</p>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* All Timesheets List */}
      {timesheets.length > 0 && (
        <div className="mt-6 bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-bold mb-4">All Timesheets</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Week</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Status</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Submitted</th>
                  <th className="px-4 py-3 text-center font-semibold text-gray-700">Action</th>
                </tr>
              </thead>
              <tbody>
                {timesheets.map((t) => (
                  <tr
                    key={t.id}
                    className={`border-b hover:bg-gray-50 cursor-pointer ${
                      selectedTimesheet?.id === t.id ? 'bg-blue-50' : ''
                    }`}
                  >
                    <td className="px-4 py-3 font-medium">
                      {format(new Date(t.week_start_date + 'T12:00:00'), 'MMM dd, yyyy')}
                    </td>
                    <td className="px-4 py-3">
                      <span
                        className={`px-2 py-1 rounded-full text-xs font-semibold uppercase ${
                          t.status === 'approved'
                            ? 'bg-green-100 text-green-700'
                            : t.status === 'pending'
                            ? 'bg-yellow-100 text-yellow-700'
                            : t.status === 'rejected'
                            ? 'bg-red-100 text-red-700'
                            : 'bg-gray-100 text-gray-700'
                        }`}
                      >
                        {t.status}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-gray-600 text-xs">
                      {t.submitted_at
                        ? format(new Date(t.submitted_at), 'MMM dd, yyyy')
                        : '-'}
                    </td>
                    <td className="px-4 py-3 text-center">
                      <button
                        onClick={() => loadTimesheet(t.id)}
                        className="text-blue-600 hover:text-blue-700 font-medium"
                      >
                        View
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}
